def fib(n):
    if n == 0:
        return 0
    prev, cur = 0, 1                      # dp[i - 2] and dp[i - 1]
    for _ in range(2, n + 1):
        prev, cur = cur, prev + cur
    return cur

int fib(int n) {
    if (n == 0) return 0;
    int prev = 0, cur = 1;                // dp[i - 2] and dp[i - 1]
    for (int i = 2; i <= n; i++) {
        int next = prev + cur;
        prev = cur;
        cur = next;
    }
    return cur;
}

