function binomial(n, k) {
  const row = new Array(k + 1).fill(0);
  row[0] = 1;                                         // row 0: C(0, 0) = 1
  for (let i = 1; i <= n; i++) {
    for (let j = Math.min(i, k); j >= 1; j--) {       // right to left: row[j - 1] is still the old row
      row[j] += row[j - 1];
    }
  }
  return row[k];
}

